import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
import {buildValidatedMigrationPlan} from './fawri/scripts/lib/postgresql-cross-lane-reconciliation.mjs';
const root=path.resolve('fawri'),dir=fs.mkdtempSync(path.join(os.tmpdir(),'fawri-field004-probe-'));
const hash=s=>createHash('sha256').update(s).digest('hex');
const read=n=>JSON.parse(fs.readFileSync(path.join(dir,n),'utf8'));
const write=(n,v)=>fs.writeFileSync(path.join(dir,n),JSON.stringify(v,null,2)+'\n');
const fingerprint=()=>Object.fromEntries(fs.readdirSync(dir).sort().map(n=>[n,hash(fs.readFileSync(path.join(dir,n)))]));
try {
 for(const name of ['create-postgresql-migration-fixture.mjs','create-transitional-migration-fixture.mjs']){
  const r=spawnSync(process.execPath,[path.join(root,'scripts/tests/fixtures',name),dir],{encoding:'utf8'});assert.equal(r.status,0,r.stderr);
 }
 const runtime=read('fawri-runtime-db.json');
 runtime.orderDraftsByConversation['conversation-1']={id:'field004-synthetic-draft',merchant_id:'merchant-1',customer_external_id:'customer-1',awaiting_field:'customer_phone',draft_data:{synthetic_marker:'field004-owned'},created_at:'2026-08-06T12:00:00.000Z',updated_at:'2026-08-06T12:00:00.000Z',expires_at:'2026-08-06T13:00:00.000Z'};
 write('fawri-runtime-db.json',runtime);
 write('processed-meta-events.json',{events:{'meta:page-1:field004-synthetic-event':'2026-08-06T12:00:00.000Z'}});
 const before=fingerprint();
 const {report,snapshot}=buildValidatedMigrationPlan({dataDirectory:dir,includeRows:true});
 assert.deepEqual(fingerprint(),before,'planner must preserve fixture files');
 const result={probe:'FIELD004_EXISTING_MIGRATION_DESTINATIONS_AND_CURRENT_LEDGER_RECONCILIATION',sourceOnly:false,layer:'LOCAL_SYNTHETIC_READ_ONLY_PLANNER_NO_SQL_HTTP_PROVIDER',toolVersion:report.tool_version,planOk:report.ok,writeReady:report.write_readiness?.ok,snapshot:snapshot.name,snapshotSha256:snapshot.sha256,errors:report.errors.map(x=>x.code),counts:{order_drafts:report.rows.order_drafts?.length||0,processed_channel_events:report.rows.processed_channel_events?.length||0,channel_inbound_events:report.rows.channel_inbound_events?.length||0},draftMapped:report.rows.order_drafts?.some(x=>x.id==='field004-synthetic-draft'&&x.draft_data?.synthetic_marker==='field004-owned'),eventMapped:report.rows.processed_channel_events?.some(x=>x.external_event_id==='meta:page-1:field004-synthetic-event'&&x.processing_status==='completed'),matchingCurrentInbound:report.rows.channel_inbound_events?.filter(x=>x.external_event_id==='meta:page-1:field004-synthetic-event').length||0,sourceFilesUnchanged:true,sourceFileFingerprints:before,writesPerformed:false,databaseConnectionUsed:false,interpretation:'Planner destination preservation only; no proof of historical-event suppression by current ingress/worker, live draft continuation, migration SQL commit or actual provider replay.'};
 fs.writeFileSync('field004-plan-probe-result.json',JSON.stringify(result,null,2)+'\n');
 console.log(JSON.stringify(result));
} finally {fs.rmSync(dir,{recursive:true,force:true});}

